#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=1L)stop("Provide project.yaml",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");`%||%`<-function(left,right)if(is.null(left)||!length(left))right else left
source(file.path(root,"app/shiny/R/project_discovery.R"),local=TRUE);source(file.path(root,"app/shiny/R/process_helpers.R"),local=TRUE);source(file.path(root,"app/shiny/R/preprocessing_status.R"),local=TRUE)
checked<-validate_project_config_path(args[[1]],root);stopifnot(checked$valid);p<-read_project_summary(checked$path,root);status<-build_sample_pipeline_status(p);selected<-head(status$sample[status$included&status$mapping=="success"],2);stopifnot(length(selected)==2);resolved<-resolve_selected_preprocessing_samples(selected,p$samples,status,"create_hit_file",force=TRUE);stopifnot(identical(resolved$requested,selected),length(resolved$eligible)==2);sample_arg<-paste(resolved$eligible,collapse=",")
scripts<-c("ytab_run_mapfastq.py","ytab_run_create_hit_file.py","ytab_run_summary_table.py","ytab_run_library_diagnostics.py");commands<-lapply(scripts,function(script)c(file.path(root,"scripts/local",script),"--project-config",checked$path,"--samples",sample_arg,"--dry-run"))
for(command in commands){stopifnot(command[[3]]==checked$path,basename(command[[3]])=="project.yaml",command[[5]]==sample_arg,nzchar(command[[5]]),length(strsplit(command[[5]],",",fixed=TRUE)[[1]])==2,grepl(selected[[1]],command[[5]],fixed=TRUE),grepl(selected[[2]],command[[5]],fixed=TRUE),grepl(" ",command[[3]],fixed=TRUE));format_command_for_display(locate_python_executable(),command)}
cat("PASS\n")
